package main

import (
	"encoding/json"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

type Message struct {
	Type    string          `json:"type"`
	Payload json.RawMessage `json:"payload"`
}

type SubscribePayload struct {
	ChannelID string `json:"channel_id"`
}

type ChatMessage struct {
	ChannelID string `json:"channel_id"`
	Content   string `json:"content"`
	SenderID  string `json:"sender_id"`
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type Hub struct {
	mu       sync.RWMutex
	channels map[string]map[*websocket.Conn]bool
}

func NewHub() *Hub {
	return &Hub{channels: make(map[string]map[*websocket.Conn]bool)}
}

func (h *Hub) Subscribe(channelID string, conn *websocket.Conn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.channels[channelID] == nil {
		h.channels[channelID] = make(map[*websocket.Conn]bool)
	}
	h.channels[channelID][conn] = true
}

func (h *Hub) Broadcast(channelID string, msg []byte) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for conn := range h.channels[channelID] {
		conn.WriteMessage(websocket.TextMessage, msg)
	}
}

var hub = NewHub()

// handleWS processes WebSocket connections.
// Authentication is handled by the upstream proxy which sets X-User-ID header.
// NOTE: Channel access control is NOT enforced here - any authenticated user
// can subscribe to any channel_id they know or guess.
func handleWS(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, raw, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg Message
		if err := json.Unmarshal(raw, &msg); err != nil {
			continue
		}

		switch msg.Type {
		case "subscribe":
			var sub SubscribePayload
			if err := json.Unmarshal(msg.Payload, &sub); err != nil {
				continue
			}
			// VULNERABILITY: No authorization check - user can subscribe to
			// any channel including private channels of other users/orgs
			hub.Subscribe(sub.ChannelID, conn)
			log.Printf("user %s subscribed to channel %s", userID, sub.ChannelID)

		case "message":
			var chat ChatMessage
			if err := json.Unmarshal(msg.Payload, &chat); err != nil {
				continue
			}
			chat.SenderID = userID
			data, _ := json.Marshal(chat)
			hub.Broadcast(chat.ChannelID, data)
		}
	}
}

func main() {
	http.HandleFunc("/ws", handleWS)
	log.Println("WebSocket server starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
